class GuardrailViolation(Exception):
    """Exception raised when a guardrail blocks a request or response.

    The error message contains the guardrail name and the scorer's rationale (matching
    the pattern ``name.*rationale``). When no rationale is available the message defaults
    to ``"blocked"``.
    """

    def __init__(self, name: str | None = None, rationale: str | None = None):
        self.name = name
        self.rationale = rationale
        if name and rationale:
            message = f"{name}: {rationale}"
        elif rationale:
            message = rationale
        else:
            message = "blocked"
        self.message = message
        super().__init__(message)


def _is_scalar_passing(value: Any) -> bool:
    """Interpret a scalar scorer value as passing (True) or failing (False).

    A boolean is returned as-is; a string is passing when it case-insensitively equals
    ``"yes"``. Any other type raises ``TypeError``.
    """
    # NB: bool must be checked before any int handling since bool is a subclass of int.
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() == "yes"
    raise TypeError(f"Scorer returned unexpected value type: {type(value).__name__}")


